WITH ranked AS (SELECT id, full_name, email, manager_id, job_title, salary, hire_date FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY level, job_title ORDER BY hire_date DESC NULLS FIRST, id) AS row_num FROM employees) ranked WHERE row_num = 1) SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, job_title, DATE_TRUNC('YEAR', hire_date) AS year_start, COUNT_IF(job_title = 'Manager') AS manager_events, SUM(CASE WHEN job_title = 'Director' THEN salary ELSE 0 END) AS director_salary, COUNT_IF(job_title = 'Engineer') AS engineer_events FROM ranked GROUP BY DATE_TRUNC('MONTH', hire_date), job_title, DATE_TRUNC('YEAR', hire_date) ORDER BY year_start DESC NULLS LAST;
